import { crewSeatOf } from "../api/crew-seats";
import type { Agent } from "../types";

/**
 * Military skins for every agent, in every office pack: the pr-patrol crew as operators
 * (public/sprites/101..109, generated by scripts/sprites/generate-tarkov-sprites.py), keyed by crew seat so a
 * renamed agent keeps its operator; any other agent gets one of them by id.
 */
const OPERATOR_SPRITES: Record<string, number> = {
  Argus: 101, // recon / marksman: reviews
  Hawk: 108, // second reviewer: marksman with shooting glasses
  Owl: 109, // third reviewer: spotter with binoculars
  Patch: 102, // engineer: review fixes
  Rivet: 106, // second fixer
  Splice: 107, // third fixer
  Medic: 103, // medic: CI fixes
  Weaver: 104, // sapper: merge conflicts
  Gate: 105, // checkpoint sentry: readiness
};

/** Sprite numbers the office must preload so no agent ever shows a missing texture. */
export const PACK_SKIN_SPRITE_NUMS = [101, 102, 103, 104, 105, 106, 107, 108, 109];

export function packSkinSpriteFor(agent: Agent): number {
  const seat = crewSeatOf(agent);
  const named = seat ? OPERATOR_SPRITES[seat] : undefined;
  if (named) return named;
  let hash = 0;
  for (let i = 0; i < agent.id.length; i += 1) hash = (hash * 31 + agent.id.charCodeAt(i)) >>> 0;
  return PACK_SKIN_SPRITE_NUMS[hash % PACK_SKIN_SPRITE_NUMS.length];
}
